mapper.select:
SELECT ds.seq, ds.name, ds.product_name AS productName, ds.price, ds.image_url AS imageUrl, ds.status, tl.dong, tl.lat, tl.lng, m.name AS sellerName, ds.created_at AS createdAt FROM direct_sale ds JOIN member m ON ds.seller_seq = m.seq LEFT JOIN trade_location tl ON ds.trade_location_seq = tl.seq
WHERE ds.status != '삭제'
AND ds.category_seq = #{dto.categorySeq}
AND ds.price >= #{dto.minPrice}
AND ds.price <= #{dto.maxPrice}
ORDER BY ds.seq DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

 	SELECT
        ds.seq, ds.name, ds.product_name AS productName,
        ds.price, ds.image_url AS imageUrl, ds.status,
        tl.dong, tl.lat, tl.lng, m.name AS sellerName, ds.created_at AS createdAt
    FROM direct_sale ds
    JOIN member m
        ON ds.seller_seq = m.seq
    JOIN trade_location tl
        ON ds.trade_location_seq = tl.seq

    WHERE ds.status != '삭제'
    	AND ds.seller_seq != #{dto.memberSeq}


	  AND ds.category_seq = #{dto.categorySeq}



	  AND tl.dong = #{dto.memberDong}


	  AND (
	    6371 * ACOS(
	      LEAST(1, GREATEST(-1,
	        COS(#{dto.memberLat} * (ACOS(-1) / 180))
	        * COS(tl.lat * (ACOS(-1) / 180))
	        * COS((tl.lng - #{dto.memberLng}) * (ACOS(-1) / 180))
	        + SIN(#{dto.memberLat} * (ACOS(-1) / 180))
	        * SIN(tl.lat * (ACOS(-1) / 180))
	      ))
	    )
	  ) <= #{dto.distanceKm}



	  AND ds.price >= #{dto.minPrice}


	  AND ds.price <= #{dto.maxPrice}


	ORDER BY ds.seq DESC
	OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY
